            "code": "import pandas as pd\n\norders = pd.DataFrame({'sku': ['A', 'A', 'X'], 'qty': [2, 1, 4]})\ncatalog = pd.DataFrame({'sku': ['A', 'B'], 'price': [100, 200]})\njoined = orders.merge(catalog, on='sku', how='left',\n                      validate='many_to_one', indicator=True)\nprint(joined['_merge'].astype('string').to_list())\nprint(joined.loc[joined['_merge'] == 'left_only', 'sku'].to_list())\nprint(len(joined) == len(orders))",
